import test from 'node:test';
import assert from 'node:assert/strict';

import { parseDuration, parseGcodeSummary } from './gcode-summary.mjs';

/** Gerçek PrusaSlicer 2.5.0 başlığından alınan satırlar (20 mm küp, 0.2 mm, %20). */
function buildRealHeader({ layers = 99 } = {}) {
  const header = [
    '; generated by PrusaSlicer 2.5.0+dfsg-4 on 2026-11-13 at 10:00:00 UTC',
    ';',
    '; external perimeters extrusion width = 0.45mm',
    '; perimeters extrusion width = 0.45mm',
    '; infill extrusion width = 0.45mm',
    '; solid infill extrusion width = 0.45mm',
    '; top infill extrusion width = 0.40mm',
    '; first layer extrusion width = 0.42mm',
    ';',
    '; filament used [mm] = 1504.88',
    '; filament used [cm3] = 3.62',
    '; filament used [g] = 4.49',
    '; filament cost = 0.11',
    '; total filament used [g] = 4.49',
    '; total filament cost = 0.11',
    '; estimated printing time (normal mode) = 19m 11s',
    ';',
    '; prusaslicer_config = begin',
    '; layer_height = 0.2',
    '; fill_density = 20%',
    '; prusaslicer_config = end',
    '',
    'M73 P0 R19',
    'M201 X1000 Y1000 Z200 E5000 ; sets maximum accelerations',
    'M82 ; use absolute distances for extrusion',
    'G92 E0',
  ];

  for (let index = 0; index < layers; index += 1) {
    header.push(
      ';LAYER_CHANGE',
      `;Z:${(0.2 * (index + 1)).toFixed(1)}`,
      ';TYPE:Perimeter',
      `G1 X10 Y10 E${(index + 1) * 15}`,
      `G1 E${(index + 1) * 15 - 2} ; retract (saf E, toplama girmez)`,
      `G1 X20 Y10 E${(index + 1) * 15 + 5}`
    );
  }

  header.push('M104 S0 ; turn off temperature', 'M84     ; disable motors', '');

  return header.join('\n');
}

test('gerçek PrusaSlicer başlığını ayrıştırır', () => {
  const summary = parseGcodeSummary(buildRealHeader());

  assert.deepEqual(summary, {
    grams: 4.49,
    printSeconds: 1151,
    layerCount: 99,
    filamentMm: 1504.88,
    supportGrams: 0,
  });
});

test('destek ekstrüzyonunu toplamdan ayrı ölçer', () => {
  // 35 mm toplam ekstrüzyonun 15 mm'si destek → 1.5 g * 15/35 = 0.6429 g.
  const text = [
    '; filament used [mm] = 150',
    '; filament used [g] = 1.5',
    '; estimated printing time (normal mode) = 10m',
    'M82',
    'G92 E0',
    ';LAYER_CHANGE',
    ';Z:0.2',
    ';TYPE:Perimeter',
    'G1 X0 Y0 E10',
    'G1 E8 ; retract (saf E)',
    ';TYPE:Support material',
    'G1 X1 Y1 E13',
    ';TYPE:Support material interface',
    'G1 X2 Y2 E18',
    ';LAYER_CHANGE',
    ';Z:0.4',
    ';TYPE:Support material',
    'G1 X3 Y3 E23',
    ';TYPE:Perimeter',
    'G1 X4 Y4 E33',
  ].join('\n');

  const summary = parseGcodeSummary(text);

  assert.equal(summary.grams, 1.5);
  assert.equal(summary.layerCount, 2);
  assert.equal(summary.supportGrams, 0.6429);
});

test('göreli ekstrüzyon modunda (M83) destek oranını hesaplar', () => {
  const text = [
    '; filament used [mm] = 60',
    '; filament used [g] = 1.2',
    'M83',
    ';LAYER_CHANGE',
    ';TYPE:Perimeter',
    'G1 X0 Y0 E10',
    'G1 E-2 ; retract',
    'G1 E2 ; unretract',
    ';TYPE:Support material',
    'G1 X1 Y1 E30',
    ';LAYER_CHANGE',
    ';TYPE:Perimeter',
    'G1 X2 Y2 E20',
  ].join('\n');

  const summary = parseGcodeSummary(text);

  // Toplam 60 mm, destek 30 mm → 1.2 g * 0.5 = 0.6 g.
  assert.equal(summary.layerCount, 2);
  assert.equal(summary.supportGrams, 0.6);
});

test('parseDuration bilinen süre biçimlerini saniyeye çevirir', () => {
  assert.equal(parseDuration('2d 3h 4m 5s'), 183845);
  assert.equal(parseDuration('1h 2m'), 3720);
  assert.equal(parseDuration('45s'), 45);
  assert.equal(parseDuration('19m 11s'), 1151);
  assert.equal(parseDuration('1d'), 86400);
  assert.equal(parseDuration(' 1h2m '), 3720);
});

test('parseDuration ayrıştırılamayan girdide null döner', () => {
  assert.equal(parseDuration('less than a minute'), null);
  assert.equal(parseDuration('1h 2x'), null);
  assert.equal(parseDuration(''), null);
  assert.equal(parseDuration(null), null);
  assert.equal(parseDuration(undefined), null);
});

test('filament satırı yoksa sonuç null döner', () => {
  const text = [
    '; total filament used [g] = 4.49',
    '; estimated printing time (normal mode) = 19m 11s',
    ';LAYER_CHANGE',
    'G1 X10 Y10 E1.0',
  ].join('\n');

  assert.equal(parseGcodeSummary(text), null);
});

test('boş metin null döner', () => {
  assert.equal(parseGcodeSummary(''), null);
  assert.equal(parseGcodeSummary('   '), null);
  assert.equal(parseGcodeSummary(null), null);
});

test('süre satırı yoksa printSeconds 0 değil null olur', () => {
  const summary = parseGcodeSummary(
    ['; filament used [g] = 4.49', ';LAYER_CHANGE'].join('\n'),
  );

  assert.equal(summary.grams, 4.49);
  assert.equal(summary.printSeconds, null);
});

test('filament mm satırı yoksa filamentMm 0 değil null olur', () => {
  const summary = parseGcodeSummary('; filament used [g] = 12.5');

  assert.equal(summary.grams, 12.5);
  assert.equal(summary.filamentMm, null);
});

test(';TYPE: yoksa katman sayısı ;LAYER_CHANGE sayısı + 1 olarak türetilir', () => {
  assert.equal(
    parseGcodeSummary('; filament used [g] = 1.00').layerCount,
    1,
  );

  const withTwoChanges = ['; filament used [g] = 1.00', ';LAYER_CHANGE', ';LAYER_CHANGE'].join(
    '\n',
  );

  assert.equal(parseGcodeSummary(withTwoChanges).layerCount, 3);
});

test('destek katmanları nesne katman sayısına eklenmez', () => {
  // Destek açıkken PrusaSlicer her katmanı iki ;LAYER_CHANGE ile yazar
  // (destek + nesne). Gerçek katman sayısı nesne bölümü olan bloklardır.
  const lines = ['; filament used [mm] = 10', '; filament used [g] = 1.00'];

  for (let index = 0; index < 5; index += 1) {
    lines.push(
      ';LAYER_CHANGE',
      ';TYPE:Support material',
      `G1 X1 Y1 E${index * 2 + 1}`,
      ';LAYER_CHANGE',
      ';TYPE:Perimeter',
      `G1 X2 Y2 E${index * 2 + 2}`
    );
  }

  const summary = parseGcodeSummary(lines.join('\n'));

  assert.equal(summary.layerCount, 5);
  assert.equal(summary.supportGrams, 0.5);
});
